package com.powercms.cms.sitepackage.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="site_container", uniqueConstraints=@UniqueConstraint(columnNames={"site_id","name"}))
public class SiteContainerEntity { @Id private UUID id; @Column(name="site_id",nullable=false) private UUID siteId; @Column(nullable=false,length=200) private String name; @Column(name="allowed_component_types",nullable=false,columnDefinition="text") private String allowedComponentTypes="[]"; @Column(nullable=false,columnDefinition="text") private String config="{}"; @Column(name="current_version",nullable=false) private int currentVersion; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; @PrePersist void create(){if(id==null)id=UUID.randomUUID();var n=Instant.now();createdAt=n;updatedAt=n;} @PreUpdate void update(){updatedAt=Instant.now();} public UUID getId(){return id;} public void setId(UUID v){id=v;} public UUID getSiteId(){return siteId;} public void setSiteId(UUID v){siteId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getAllowedComponentTypes(){return allowedComponentTypes;} public void setAllowedComponentTypes(String v){allowedComponentTypes=v;} public String getConfig(){return config;} public void setConfig(String v){config=v;} public int getCurrentVersion(){return currentVersion;} public void setCurrentVersion(int v){currentVersion=v;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} }